import torch
from _tensorviz_change_config import WIDTH, HEADS
class Model(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.up = torch.nn.Linear(8, WIDTH)
        self.tied = self.up
        self.norm = torch.nn.LayerNorm(WIDTH)
        self.down = torch.nn.Linear(WIDTH, 4)
    def forward(self, x):
        hidden = self.norm(self.up(x) + self.tied(x))
        split = hidden.reshape(hidden.shape[0], hidden.shape[1])
        return self.down(split.flatten(1))

import torch
from _tensorviz_change_config import WIDTH
class Model(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.up = torch.nn.Linear(8, WIDTH, bias=False)
        self.tied = self.up
        self.other = torch.nn.Linear(8, 24 - WIDTH, bias=False)
        self.other.weight = self.up.weight
    def forward(self, x):
        return self.up(x) + self.other(x)
